def get_ludic(n):
    def is_ludic(num):
        if num < 2:
            return True
        factors = []
        i = 2
        temp = num
        while i * i <= temp:
            if temp % i == 0:
                factors.append(i)
                temp //= i
            else:
                i += 1
        if temp > 1:
            factors.append(temp)

        for factor in factors:
            if not is_ludic(factor):
                return False
        return True

    result = []
    for i in range(n + 1):
        if is_ludic(i):
            result.append(i)
    return result

